# Simulate PC2 cleavage at the KR motif
sequence = ""
cleavage_site = "KR"
idx = sequence.find(cleavage_site)
if idx != -1:
    print(f"Cleavage site found at position {idx}.")
    print(f"Fragment 1 (N-term): {sequence[:idx+2]}")
    print(f"Fragment 2 (C-term): {sequence[idx+2:]}")
else:
    print("No cleavage site found.")
